#!/usr/bin/env node
/**
 * Writes `src/version.generated.ts` from this package's `package.json`.
 *
 * The transport reports the constant to the host in `BLOCK_READY` (`sdkVersion`),
 * so it has to be the version that is actually published. Three things keep it
 * that way, and they are the same three `@civitai/components` relies on:
 *   - `build` runs this first, so a tarball cannot carry a stale constant;
 *   - the root `release:version` runs it right after `changeset version`, so
 *     the Version Packages PR carries the regenerated file with the bump;
 *   - `scripts/check-generated-version.mjs` (repo root) fails CI when the
 *     COMMITTED file and `package.json` disagree.
 *
 * The output shape is what that check and `scripts/ci-lanes.mjs` parse: one
 * `export const VERSION = "…";` line. Keep it.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const pkgRoot = join(dirname(fileURLToPath(import.meta.url)), '..');
const { version } = JSON.parse(readFileSync(join(pkgRoot, 'package.json'), 'utf8'));

writeFileSync(
  join(pkgRoot, 'src', 'version.generated.ts'),
  `/* AUTOGENERATED from package.json by scripts/gen-version.mjs. DO NOT EDIT. */\n\n` +
    `/** This package's version, reported to the host as \`sdkVersion\` in \`BLOCK_READY\`. */\n` +
    `export const VERSION = ${JSON.stringify(version)};\n`,
);

console.log(`[gen-version] wrote src/version.generated.ts (${version})`);
